#define MAXN 2005
int adj[MAXN][MAXN], deg[MAXN], n;
int memo[MAXN][MAXN];
// -1 = uncomputed

int solve(int t, int a) {
    if (memo[t][a] != -1) return memo[t][a];
    memo[t][a] = -2; // computing
    int best = 0; // Takahashi maximizes
    for (int i = 0; i < deg[t]; i++) {
        int nt = adj[t][i];
        int worst = 1<<28; // Aoki minimizes
        for (int j = 0; j < deg[a]; j++) {
            int na = adj[a][j];
            if (nt == na) { worst = 1; break; }
            int v = 1 + solve(nt, na);
            if (v < worst) worst = v;
        }
        if (worst > best) best = worst;
    }
    memo[t][a] = best;
    return best;
}

