typedef struct Edge {
    int to, next;
} Edge;

int main(void) {
    int N, u, v;
    if (scanf("%d %d %d", &N, &u, &v) != 3) return 0;
    u--; v--;

    int *head = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) head[i] = -1;

    Edge *edges = (Edge *)malloc(sizeof(Edge) * 2 * (N - 1));
    int ecnt = 0;

    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        a--; b--;
        edges[ecnt].to = b;
        edges[ecnt].next = head[a];
        head[a] = ecnt++;

        edges[ecnt].to = a;
        edges[ecnt].next = head[b];
        head[b] = ecnt++;
    }

    int *distU = (int *)malloc(sizeof(int) * N);
    int *distV = (int *)malloc(sizeof(int) * N);
    int *queue = (int *)malloc(sizeof(int) * N);

    for (int i = 0; i < N; i++) distU[i] = distV[i] = -1;

    // BFS from u
    int front = 0, back = 0;
    queue[back++] = u;
    distU[u] = 0;
    while (front < back) {
        int x = queue[front++];
        for (int e = head[x]; e != -1; e = edges[e].next) {
            int y = edges[e].to;
            if (distU[y] == -1) {
                distU[y] = distU[x] + 1;
                queue[back++] = y;
            }
        }
    }

    // BFS from v
    front = back = 0;
    queue[back++] = v;
    distV[v] = 0;
    while (front < back) {
        int x = queue[front++];
        for (int e = head[x]; e != -1; e = edges[e].next) {
            int y = edges[e].to;
            if (distV[y] == -1) {
                distV[y] = distV[x] + 1;
                queue[back++] = y;
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < N; i++) {
        if (distU[i] < distV[i]) {
            if (distV[i] - 1 > ans) ans = distV[i] - 1;
        }
    }

    printf("%d\n", ans);

    free(head);
    free(edges);
    free(distU);
    free(distV);
    free(queue);
    return 0;
}

