            int v = sc.nextInt() - 1;
            graph.get(u).add(v);
            graph.get(v).add(u);
        }

        int[] distT = bfs(graph, tStart);
        int[] distA = bfs(graph, aStart);

        int answer = 0;
        for (int i = 0; i < N; i++) {
            if (distT[i] > distA[i]) {
                answer = Math.max(answer, distT[i]);
            }
        }
        System.out.println(answer);
    }

    static int[] bfs(List<List<Integer>> graph, int start) {
        int n = graph.size();
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Queue<Integer> q = new LinkedList<>();
        dist[start] = 0;
        q.add(start);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph.get(u)) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                }
            }
        }
        return dist;
    }
