public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static List<Integer>[] graph;
    static int[] distT, distA;

    static void bfs(int start, int[] dist) {
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[start] = 0;
        q.add(start);

        while (!q.isEmpty()) {
            int v = q.poll();
            for (int to : graph[v]) {
                if (dist[to] == -1) {
                    dist[to] = dist[v] + 1;
                    q.add(to);
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int u = fs.nextInt() - 1; // Takahashi
        int v = fs.nextInt() - 1; // Aoki

        graph = new ArrayList[N];
        for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            graph[a].add(b);
            graph[b].add(a);
        }

        distT = new int[N];
        distA = new int[N];

        bfs(u, distT);
        bfs(v, distA);

        int ans = 0;
        for (int i = 0; i < N; i++) {
            // Takahashi can safely stay in vertices where he arrives strictly earlier.
            // Aoki can catch him one move later than Aoki's distance to that vertex.
            if (distT[i] < distA[i]) {
                ans = Math.max(ans, distA[i] - 1);
            }
        }

        System.out.println(ans);
    }
}

