#include <bits/stdc++.h>
using namespace std;

/*
ABC 148 F - Playing Tag on Tree

There is a tree with N vertices.
Takahashi starts at u, Aoki starts at v.

Both move alternately to an adjacent vertex, with Takahashi moving first.
Takahashi wants to maximize the number of moves Aoki makes before Aoki catches him,
and Aoki wants to minimize it.

Key fact:
Takahashi can safely move only to vertices x where dist(u, x) < dist(v, x),
because if dist(v, x) <= dist(u, x), Aoki can reach x no later than Takahashi.

Among all such safe vertices, Takahashi wants to get as far as possible from Aoki.
If he ends at a safe vertex x, then Aoki will eventually catch him after dist(v, x) - 1 moves by Aoki.

So answer = max(dist(v, x) - 1) over all x with dist(u, x) < dist(v, x).

We compute distances from u and v by BFS/DFS on the tree.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, u, v;
    cin >> N >> u >> v;
    --u; --v;

    vector<vector<int>> g(N);
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    auto bfs = [&](int s) {
        vector<int> dist(N, -1);
        queue<int> q;
        dist[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int x = q.front();
            q.pop();
            for (int nx : g[x]) {
                if (dist[nx] != -1) continue;
                dist[nx] = dist[x] + 1;
                q.push(nx);
            }
        }
        return dist;
    };

    vector<int> du = bfs(u);
    vector<int> dv = bfs(v);

    int ans = 0;
    for (int i = 0; i < N; ++i) {
        if (du[i] < dv[i]) {
            ans = max(ans, dv[i] - 1);
        }
    }

    cout << ans << '\n';
    return 0;
}
